import { useCallback, useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { apiRequest } from './api.js';
import { GuidedEvaluatePage, GuidedIssuesPage } from './GuidedPages.js';
import { EvalSetPage, FindingsPage, RegressionPage, RunsPage } from './AdaptivePages.js';

type Json = Record<string, any>;
type PageKey = 'home' | 'projects' | 'evaluate' | 'issues' | 'eval-set' | 'runs' | 'findings' | 'fixes' | 'regression';
type Navigate = (target: PageKey | string) => void;
const navigation: Array<{ key: PageKey; label: string; note: string }> = [
  { key: 'projects', label: '项目', note: '添加与切换' },
  { key: 'eval-set', label: '评测集', note: '案例与覆盖' },
  { key: 'runs', label: '运行', note: '结果与证据' },
  { key: 'findings', label: '发现', note: 'Badcase 谱系' },
  { key: 'fixes', label: '修复', note: 'Agent 与复测' },
  { key: 'regression', label: '回归', note: '长期增强' },
];
const pageLabels: Record<PageKey, string> = { home: '使用说明', projects: '项目', evaluate: '评测', issues: '问题', 'eval-set': '评测集', runs: '运行', findings: '发现', fixes: '修复', regression: '回归' };
const stages = ['readiness', 'scan', 'background', 'blueprint', 'cases', 'run', 'report'];
const stageLabels: Record<string, string> = { readiness: '检查项目', scan: '扫描证据', background: '理解产品', blueprint: '建立标准', cases: '生成案例', run: '真实运行', report: '整理报告' };
const issueLabels: Record<string, string> = { functional_bug: '功能没有按预期工作', journey_breakpoint: '用户路径中断', discoverability_issue: '入口不容易找到', usability_issue: '操作不够顺手', path_efficiency_issue: '完成路径过长', repeated_input_issue: '需要重复输入', content_clarity_issue: '内容难以理解', interaction_feedback_issue: '操作后缺少反馈', recovery_issue: '出错后难以恢复', trust_issue: '信息不足以建立信任', accessibility_issue: '无障碍体验问题', abandonment_risk: '用户可能放弃' };

function routePage(): PageKey { const key = window.location.pathname.split('/').filter(Boolean)[0] as PageKey | undefined; return key && key in pageLabels ? key : 'home'; }
function queryValue(name: string): string { return new URLSearchParams(window.location.search).get(name) ?? ''; }
function focusAnchor(id: string): void { let attempts = 0; const locate = () => { const fixId = queryValue('fixTaskId'); const cards = [...document.querySelectorAll<HTMLElement>('.fix-card')]; const fixCard = id === 'fix-next-action' ? cards.find((item) => !fixId || item.textContent?.includes(fixId)) ?? cards[0] ?? null : null; const target = document.getElementById(id) ?? (id === 'project-next-action' ? document.querySelector<HTMLElement>('.project-card.active') : null) ?? fixCard; if (!target && attempts < 20) { attempts += 1; window.setTimeout(locate, 100); return; } if (!target) return; target.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'center' }); target.setAttribute('tabindex', '-1'); target.focus({ preventScroll: true }); target.classList.add('guided-highlight'); window.setTimeout(() => target.classList.remove('guided-highlight'), 1800); }; window.setTimeout(locate, 80); }
function useApi<T>(path: string | null): { data: T | null; loading: boolean; error: string | null; reload: () => void } {
  const [data, setData] = useState<T | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null); const [version, setVersion] = useState(0);
  useEffect(() => { let active = true; if (!path) { setData(null); setLoading(false); setError(null); return () => { active = false; }; } setLoading(true); setError(null); apiRequest<T>(path).then((value) => { if (active) setData(value); }).catch((cause) => { if (active) setError(cause instanceof Error ? cause.message : String(cause)); }).finally(() => { if (active) setLoading(false); }); return () => { active = false; }; }, [path, version]);
  return { data, loading, error, reload: () => setVersion((value) => value + 1) };
}
function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: string }) { return <span className={`badge ${tone}`}>{children}</span>; }
function Button({ children, tone = 'primary', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { tone?: string }) { return <button className={`button ${tone}`} {...props}>{children}</button>; }
function PageHeader({ step, title, intro, action }: { step: string; title: string; intro: string; action?: ReactNode }) { return <header className="page-header"><div><span className="eyebrow">{step}</span><h1>{title}</h1><p>{intro}</p></div>{action}</header>; }
function Skeleton({ rows = 4 }: { rows?: number }) { return <div className="skeleton-stack" aria-label="正在加载">{Array.from({ length: rows }, (_, index) => <div className="skeleton" key={index}/>)}</div>; }
function EmptyState({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) { return <section className="state-card"><span className="state-icon">○</span><div><h2>{title}</h2><p>{detail}</p>{action}</div></section>; }
function ErrorPanel({ message, retry }: { message: string; retry?: () => void }) { return <section className="state-card error" role="alert"><span className="state-icon">!</span><div><h2>这一步没有完成</h2><p>{message}</p>{retry && <Button tone="secondary" onClick={retry}>重新尝试</Button>}</div></section>; }
function Modal({ title, children, onClose, actions }: { title: string; children: ReactNode; onClose: () => void; actions: ReactNode }) { useEffect(() => { const close = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); }; window.addEventListener('keydown', close); return () => window.removeEventListener('keydown', close); }, [onClose]); return <div className="modal-backdrop"><div className="modal wide" role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><div><span className="eyebrow">REVIEW</span><h2>{title}</h2></div><button className="icon-button" aria-label="关闭" onClick={onClose}>×</button></div><div className="modal-body">{children}</div><div className="modal-actions">{actions}</div></div></div>; }
function Toast({ message }: { message: string | null }) { return message ? <div className="toast" role="status">{message}</div> : null; }
function ServiceRecovery({ message, retry }: { message: string; retry: () => void }) { return <section className="service-recovery"><div className="state-card error" role="alert"><span className="state-icon">!</span><div><span className="eyebrow">本地服务</span><h1>本地工作台没有连接成功</h1><p>{message}</p><p>项目数据没有丢失，但添加项目、运行评测和查看证据暂时不可用。</p><Button onClick={retry}>重新连接</Button><details className="advanced"><summary>高级详情：如何重新启动</summary><p className="mono">npm run dashboard</p></details></div></div></section>; }

function formatDuration(durationMs: number | null | undefined): string { if (!durationMs) return '—'; const seconds = Math.round(durationMs / 1000); const minutes = Math.floor(seconds / 60); return `${String(minutes).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`; }
function relativeTime(value: string): string { const minutes = Math.max(0, Math.round((Date.now() - new Date(value).getTime()) / 60_000)); if (minutes < 1) return '刚刚'; if (minutes < 60) return `${minutes} 分钟前`; const hours = Math.round(minutes / 60); if (hours < 24) return `${hours} 小时前`; return `${Math.round(hours / 24)} 天前`; }

function IssueDetail({ issue, onClose, onDismiss, onFix }: { issue: Json; onClose: () => void; onDismiss: () => void; onFix: () => void }) {
  useEffect(() => { const close = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); }; window.addEventListener('keydown', close); return () => window.removeEventListener('keydown', close); }, [onClose]);
  const failedIndex = typeof issue.location?.stepIndex === 'number' ? issue.location.stepIndex : null;
  return <div className="issue-drawer-backdrop"><aside className="issue-drawer" role="dialog" aria-modal="true" aria-label={`问题详情：${issueLabels[issue.type] ?? issue.type}`}><header className="issue-drawer-head"><div><span className="eyebrow">问题详情</span><h2>{issueLabels[issue.type] ?? issue.type}</h2><p>{issue.failureOrAbandonmentPoint ?? '用户没有完成目标。'}</p></div><button autoFocus className="icon-button" aria-label="返回问题列表" onClick={onClose}>×</button></header><div className="issue-drawer-body"><section className="issue-summary-grid"><article><span>发生页面</span><b>{issue.location?.page ?? '旧记录未定位到具体页面'}</b></article><article><span>受影响功能</span><b>{issue.featureId ?? '未识别'}</b></article><article><span>用户影响</span><b>无法顺利完成“{issue.userGoal}”</b></article><article><span>定位结果</span><b>{issue.location?.target ?? issue.location?.stepLabel ?? '尚未定位到具体控件'}</b></article></section><section className="evidence-section"><div className="section-title"><span>01</span><div><h3>用户卡在哪一步</h3><p>红色步骤是证据能够定位到的失败位置。</p></div></div>{failedIndex === null && <p className="evidence-boundary">这是一条旧记录，现有证据不能可靠定位到具体步骤。</p>}<ol className="path-steps">{(issue.actualPath ?? []).map((path: string, index: number) => <li className={failedIndex === index ? 'failed' : ''} key={`${path}-${index}`}><span>{index + 1}</span><div><b>{path}</b>{failedIndex === index && <small>问题发生在这里</small>}</div></li>)}</ol></section><section className="evidence-section"><div className="section-title"><span>02</span><div><h3>原本应该怎样完成</h3><p>这是评测前定义的合理用户路径。</p></div></div><ol className="expected-steps">{(issue.shortestReasonablePath ?? []).map((path: string, index: number) => <li key={`${path}-${index}`}>{path}</li>)}</ol></section><section className="evidence-section"><div className="section-title"><span>03</span><div><h3>我们实际看到了什么</h3><p>每条结论都对应可打开的本地证据。</p></div></div><div className="evidence-items">{(issue.evidenceItems ?? []).map((item: Json) => <article key={item.evidenceId}><div><Badge>{item.type === 'screenshot' ? '截图' : item.type === 'trace' ? '操作轨迹' : item.type === 'console' ? '控制台' : item.type === 'network' ? '网络' : '文件'}</Badge><h4>{item.title}</h4><p>{item.observation}</p>{typeof item.relatedStepIndex === 'number' && <small>对应第 {item.relatedStepIndex + 1} 步</small>}</div>{item.type === 'screenshot' ? <a href={`/api/evidence-file?path=${encodeURIComponent(item.sourcePath)}`} target="_blank" rel="noreferrer"><img src={`/api/evidence-file?path=${encodeURIComponent(item.sourcePath)}`} alt={`${item.title}，对应问题步骤`}/></a> : <a className="evidence-open" href={`/api/evidence-file?path=${encodeURIComponent(item.sourcePath)}`} target="_blank" rel="noreferrer">打开原始证据</a>}</article>)}</div>{!(issue.evidenceItems ?? []).length && <p className="evidence-boundary">本次没有保存可直接打开的证据，结论需要人工复核。</p>}</section><section className="evidence-section two-evidence-columns"><article><div className="section-title"><span>04</span><div><h3>问题可能在哪里</h3><p>以下是推测，不是已经证明的根因。</p></div></div><p>{issue.causeHypothesis ?? '现有证据不足，尚不能可靠判断根因。'}</p><p className="evidence-boundary">建议代码位置：{issue.location?.sourceFile ?? '尚未定位到具体代码文件'}</p></article><article><div className="section-title"><span>05</span><div><h3>建议怎样解决</h3><p>修改后仍需用同一任务复测。</p></div></div><ol>{(issue.resolutionSteps ?? [issue.recommendation]).map((item: string) => <li key={item}>{item}</li>)}</ol><h4>复测标准</h4><ul>{(issue.verificationSteps ?? []).map((item: string) => <li key={item}>{item}</li>)}</ul></article></section><p className="authenticity">这是模拟用户和工程证据，不代表真实用户满意度或业务效果；可能原因必须由代码检查或修复复测进一步确认。</p></div><footer className="issue-drawer-actions"><Button tone="secondary" onClick={onDismiss}>暂不处理</Button><Button onClick={onFix}>选择 AI 修复</Button><Button tone="secondary" onClick={onClose}>返回问题列表</Button></footer></aside></div>;
}

function HomePage({ active, go }: { active: Json | null; go: Navigate }) {
  const agents = useApi<Json[]>('/agents');
  const guidance = useApi<Json>(`/guidance${active ? `?projectId=${encodeURIComponent(active.projectId)}` : ''}`);
  const records = useApi<Json[]>(active ? `/evaluation-records?projectId=${encodeURIComponent(active.projectId)}` : null);
  const latest = records.data?.[0] ?? null;
  const issues = useApi<Json[]>(active && latest ? `/issues?projectId=${encodeURIComponent(active.projectId)}&evaluationId=${encodeURIComponent(latest.evaluationId)}` : null);
  const tasks = useApi<Json[]>(active ? `/fix-tasks?projectId=${encodeURIComponent(active.projectId)}` : null);
  const visibleIssues = (issues.data ?? []).filter((item) => !item.dismissed).sort((a, b) => Number(a.severity?.slice(1) ?? 9) - Number(b.severity?.slice(1) ?? 9));
  const worst = visibleIssues[0]; const severeCount = latest?.severeIssueCount ?? 0; const relatedTask = worst ? tasks.data?.find((item) => item.issueId === worst.issueId) : null;
  const taskItems = guidance.data?.steps ?? [];
  return <><PageHeader step="GET STARTED / 新手引导" title={guidance.data?.currentStep === 'complete' ? '这一轮已经完成' : '跟着当前任务往下做'} intro="系统已经替你判断当前该做什么；每完成一步都会自动带你到下一步。" action={<Badge>{agents.loading ? '正在检查 AI 工具' : `本机已发现 ${(agents.data ?? []).filter((item) => item.installed).length} 个可用工具`}</Badge>}/><div className="home-grid"><section className="panel home-tasks" aria-label="EvalPilot 使用流程">{guidance.loading ? <Skeleton rows={4}/> : guidance.error ? <ErrorPanel message={guidance.error} retry={guidance.reload}/> : taskItems.map((item: Json, index: number) => <button className={`home-task ${item.status === 'current' || item.status === 'attention' ? 'current' : ''}`} key={item.id} onClick={() => go(item.route)}><span className="home-task-number">{String(index + 1).padStart(2, '0')}</span><span className="home-task-copy"><b>{item.title}</b><small>{item.description}</small></span>{item.status === 'completed' ? <Badge tone="success">已完成</Badge> : item.status === 'current' ? <span className="button primary home-inline-cta">{item.actionLabel}</span> : item.status === 'attention' ? <Badge tone="warning">需要继续</Badge> : <Badge>等待前一步</Badge>}</button>)}</section><aside className="panel last-evaluation" aria-label="上一次评测">{!active ? <EmptyState title="还没有连接项目" detail="连接一个本地项目后，这里会显示它最近一次评测的结果。" action={<Button onClick={() => go('/projects')}>连接第一个项目</Button>}/> : records.loading ? <><div className="last-evaluation-head"><div><h2>上一次评测</h2><small>正在读取当前项目历史</small></div></div><Skeleton rows={3}/></> : records.error ? <ErrorPanel message={records.error} retry={records.reload}/> : !latest ? <EmptyState title="还没有评测记录" detail={`完成「${active.name}」的第一次评测后，结果会出现在这里。`} action={<Button onClick={() => go('/evaluate#recommended-evaluation')}>开始第一次评测</Button>}/> : <><div className="last-evaluation-head"><div><h2>上一次评测</h2><small>{new Date(latest.startedAt).toLocaleString('zh-CN', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false })} · {relativeTime(latest.startedAt)}</small></div><Badge tone={latest.status === 'completed' ? 'success' : latest.status === 'failed' ? 'danger' : 'purple'}>{latest.status === 'completed' ? '已完成' : latest.status === 'failed' ? '未完成' : '进行中'}</Badge></div><div className="last-project"><span className="last-project-mark">{active.name.slice(0, 2).toUpperCase()}</span><div><b>{active.name}</b><small>{latest.displayName}</small></div></div><article className="last-card"><div className="card-heading"><b>上线判断</b><Badge tone={latest.verdict === 'can_continue' ? 'success' : latest.verdict === 'needs_attention' ? 'warning' : 'neutral'}>{latest.verdict === 'can_continue' ? '可以继续' : latest.verdict === 'needs_attention' ? '需要处理' : '等待结果'}</Badge></div><strong className={severeCount ? 'last-signal warning-text' : 'last-signal success-text'}>{severeCount ? `${severeCount} 个严重问题` : '没有 P0 / P1 问题'}</strong><div className="last-stats"><div><strong>{Math.max(0, (latest.issueCount ?? 0) - severeCount)}</strong><small>一般问题</small></div><div><strong className={severeCount ? 'warning-text' : ''}>{severeCount}</strong><small>P0 / P1</small></div><div><strong>{formatDuration(latest.durationMs)}</strong><small>耗时</small></div></div>{latest.notApplicableCount > 0 && <p>{latest.notApplicableCount} 项检查因项目没有对应能力而跳过，不计为失败。</p>}</article>{issues.loading ? <Skeleton rows={1}/> : issues.error ? <p className="inline-error">问题摘要读取失败：{issues.error}</p> : worst ? <article className="last-card"><div className="card-heading"><b>最需要关注</b><Badge tone="purple">{worst.featureId ?? worst.severity}</Badge></div><p>{worst.failureOrAbandonmentPoint ?? worst.recommendation ?? '用户没有完成目标。'}</p><button className="text-action" onClick={() => go(`/issues?evaluationId=${encodeURIComponent(latest.evaluationId)}&issueId=${encodeURIComponent(worst.issueId)}#evaluation-summary`)}><span>{worst.evidenceItems?.length ? '有分步证据和操作轨迹' : '查看问题说明'}</span><b>定位问题 →</b></button></article> : <article className="last-card"><div className="card-heading"><b>最需要关注</b><Badge tone={latest.verdict === 'needs_attention' ? 'warning' : 'success'}>{latest.verdict === 'needs_attention' ? '闭环仍有缺口' : '暂无结构化问题'}</Badge></div><p>{latest.verdict === 'needs_attention' ? '运行结果显示用户闭环未完成，但本次没有生成结构化问题，需要回看轨迹。' : '本次没有生成待处理问题；仍建议结合真实用户反馈判断。'}</p></article>}<article className="last-card"><div className="card-heading"><b>修复状态</b><Badge tone={relatedTask?.status === 'ready_to_apply' ? 'success' : relatedTask ? 'purple' : 'neutral'}>{relatedTask?.status === 'ready_to_apply' ? '等待应用' : relatedTask ? '处理中' : '尚未处理'}</Badge></div><p>{relatedTask ? '已建立隔离修复任务，可以查看 AI 工具的进度和复测结果。' : '发现问题后，可以选择本机 AI 工具在隔离分支尝试修复。'}</p></article><button className="home-record-link" onClick={() => go(`/issues?evaluationId=${encodeURIComponent(latest.evaluationId)}#evaluation-summary`)}>打开完整评测记录 →</button>{latest.legacyEvidenceIncomplete && <p className="legacy-note">旧记录，证据关联不完整。</p>}</>}</aside></div></>;
}

function ProjectsPage({ registry, reload, go }: { registry: Json; reload: () => void; go: Navigate }) {
  const agents = useApi<Json[]>('/agents'); const [adding, setAdding] = useState(false); const [submitting, setSubmitting] = useState(false); const [starting, setStarting] = useState<string | null>(null); const [discovering, setDiscovering] = useState(false); const [candidates, setCandidates] = useState<Json[]>([]); const [error, setError] = useState<string | null>(null); const [notice, setNotice] = useState<string | null>(null);
  const [form, setForm] = useState({ name: '', projectRoot: '', targetUrl: 'http://localhost:3000', importSource: 'manual', preferredAgent: null as string | null }); const [fields, setFields] = useState<Record<string, string>>({});
  const validCandidates = candidates.filter((candidate) => candidate.pathValid);
  function focusProjectConfirmation() { window.setTimeout(() => { const target = document.getElementById('project-confirmation'); if (!target) return; target.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' }); target.focus({ preventScroll: true }); target.classList.add('guided-highlight'); window.setTimeout(() => target.classList.remove('guided-highlight'), 1800); }, 40); }
  async function submit(event: FormEvent) { event.preventDefault(); const next: Record<string, string> = {}; if (!form.projectRoot.trim()) next.projectRoot = '请选择或填写项目文件夹。'; try { new URL(form.targetUrl); } catch { next.targetUrl = '请输入完整网址，例如 http://localhost:3000。'; } setFields(next); if (Object.keys(next).length) return; setSubmitting(true); setError(null); try { const project = await apiRequest<Json>('/projects', { method: 'POST', body: JSON.stringify(form) }); setAdding(false); setForm({ name: '', projectRoot: '', targetUrl: 'http://localhost:3000', importSource: 'manual', preferredAgent: null }); reload(); if (project.status === 'ready') { setNotice(`已添加「${project.name}」。准备好后点击“开始核心评测”，页面不会自动跳走。`); focusAnchor('project-next-action'); } else { setNotice(`已添加「${project.name}」，下一步需要启动页面。`); focusAnchor('project-next-action'); } } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } finally { setSubmitting(false); } }
  async function pickFolder() { setError(null); try { const result = await apiRequest<Json>('/system/pick-directory', { method: 'POST', body: '{}' }); setForm((value) => ({ ...value, name: value.name || result.path.split('/').filter(Boolean).at(-1) || '', projectRoot: result.path, importSource: 'folder', preferredAgent: null })); setNotice('文件夹已选择，请确认项目名称和测试网址。'); focusProjectConfirmation(); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } }
  async function discoverRecent() { setDiscovering(true); setError(null); setNotice(null); try { const items = await apiRequest<Json[]>('/workspace-candidates', { method: 'POST', body: JSON.stringify({ confirmed: true, providers: ['codex','claude_code','antigravity'] }) }); setCandidates(items); const available = items.filter((item) => item.pathValid); setNotice(available.length ? `找到了 ${available.length} 个可以选择的项目。` : '没有找到可用项目，请从 Mac 选择项目文件夹。'); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } finally { setDiscovering(false); } }
  function chooseCandidate(candidate: Json) { const preferredAgent = candidate.sourceAgents?.[0] ?? null; setForm((value) => ({ ...value, name: candidate.name, projectRoot: candidate.projectRoot, importSource: preferredAgent ?? 'manual', preferredAgent })); setNotice(`已选择「${candidate.name}」，下一步只需确认测试网址。`); focusProjectConfirmation(); }
  async function activate(id: string) { setStarting(id); setError(null); try { await apiRequest(`/projects/${id}/activate`, { method: 'POST', body: JSON.stringify({ confirmed: true }) }); reload(); setNotice('已切换项目。'); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } finally { setStarting(null); } }
  async function start(project: Json) { setStarting(project.projectId); setError(null); try { await apiRequest(`/projects/${project.projectId}/start`, { method: 'POST', body: JSON.stringify({ confirmed: true, command: project.startCommand }) }); reload(); setNotice('项目已启动。准备好后点击“开始核心评测”，页面不会自动跳走。'); focusAnchor('project-next-action'); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } finally { setStarting(null); } }
  return <><PageHeader step="01 / PROJECTS" title="选择要评测的项目" intro="每个项目独立保存评测历史。EvalPilot 会帮你从常用开发工具中找到近期项目，修复前仍会再次授权。" action={<Button onClick={() => setAdding(true)}>＋ 智能添加项目</Button>} />
    {error && <ErrorPanel message={error}/>} {!registry.projects?.length ? <EmptyState title="还没有项目" detail="添加一个本地 Web 项目后，EvalPilot 会帮助检查启动方式和测试网址。" action={<Button onClick={() => setAdding(true)}>添加第一个项目</Button>}/> : <section className="project-grid">{registry.projects.map((project: Json) => { const current = project.projectId === registry.activeProjectId; const summary = registry.summaries?.find((item: Json) => item.projectId === project.projectId); return <article className={`project-card ${current ? 'active' : ''}`} key={project.projectId}><div className="card-heading"><Badge tone={current ? 'success' : 'neutral'}>{current ? '● 当前项目' : '可切换'}</Badge><Badge tone={project.status === 'ready' ? 'success' : 'warning'}>{project.status === 'ready' ? '可以评测' : '需要启动'}</Badge></div><h2>{project.name}</h2><p className="mono">{project.targetUrl}</p><small>{project.projectRoot}</small><div className="project-facts"><span>最近评测<b>{summary?.lastEvaluationAt ? new Date(summary.lastEvaluationAt).toLocaleString('zh-CN') : '尚未评测'}</b></span><span>严重问题<b className={summary?.severeIssueCount ? 'danger-text' : ''}>{summary?.severeIssueCount ?? 0}</b></span></div><div className="card-actions">{!current && <Button tone="secondary" disabled={starting === project.projectId} onClick={() => activate(project.projectId)}>{starting === project.projectId ? '正在切换…' : '切换到此项目'}</Button>}{current && project.status !== 'ready' && <Button disabled={starting === project.projectId} onClick={() => start(project)}>{starting === project.projectId ? '正在启动…' : '确认并启动项目'}</Button>}{current && project.status === 'ready' && <Button onClick={() => go('evaluate')}>开始核心评测</Button>}</div></article>; })}</section>}
    {adding && <Modal title="添加本地项目" onClose={() => setAdding(false)} actions={<><Button tone="secondary" disabled={submitting} onClick={() => setAdding(false)}>取消</Button><Button disabled={submitting || !form.projectRoot} form="project-form" type="submit">{submitting ? '正在检查并添加…' : '确认并添加项目'}</Button></>}><form id="project-form" className="form-stack" onSubmit={submit}><section className="project-discovery-start"><span className="eyebrow">第一步</span><h3>让系统帮你找到最近项目</h3><p>项目就是 Mac 上的文件夹。系统会查看 Codex 和 Antigravity 最近打开过哪些文件夹，并自动列出里面的项目。</p><Button type="button" disabled={discovering} onClick={discoverRecent}>{discovering ? '正在查找最近项目…' : '帮我找到最近项目'}</Button><small>只读取文件夹路径和项目标记，不读取对话、Prompt、密钥或代码内容。</small></section>{discovering && <Skeleton rows={3}/>} {!discovering && validCandidates.length > 0 && <section><div className="card-heading"><div><span className="eyebrow">第二步</span><h3>选择你认识的项目</h3></div><Badge tone="success">找到 {validCandidates.length} 个</Badge></div><div className="candidate-list">{validCandidates.map((candidate) => { const selected = form.projectRoot === candidate.projectRoot; return <button className={selected ? 'selected' : ''} type="button" key={candidate.candidateId} onClick={() => chooseCandidate(candidate)}><span><b>{candidate.name}</b><small>{candidate.stack?.join(' · ') || '本地项目'} · 最近在 {candidate.sourceAgents?.map((name: string) => name === 'claude_code' ? 'Claude Code' : name === 'antigravity' ? 'Antigravity' : 'Codex').join(' / ')} 使用</small></span><Badge tone={selected ? 'success' : 'neutral'}>{selected ? '已选择' : '使用这个项目'}</Badge></button>; })}</div></section>} {!discovering && candidates.length > 0 && !validCandidates.length && <p className="inline-error">找到的记录已经失效，请从 Mac 重新选择项目文件夹。</p>}<section className="project-folder-fallback"><h3>{validCandidates.length ? '没有看到我的项目？' : '也可以直接从 Mac 选择'}</h3><p>选择包含项目名称和源代码的最外层文件夹，不需要输入路径。</p><Button tone="secondary" type="button" onClick={pickFolder}>打开 Mac 文件夹选择器</Button></section><section id="project-confirmation" className="project-confirmation" tabIndex={-1}><div className="card-heading"><div><span className="eyebrow">最后一步</span><h3>确认这个项目</h3></div>{form.projectRoot && <Badge tone="success">已选择项目</Badge>}</div>{form.projectRoot ? <p className="selected-project-summary" role="status">当前选择：<b>{form.name || form.projectRoot.split('/').filter(Boolean).at(-1)}</b></p> : <p className="muted">先在上面选择一个项目，才能继续添加。</p>}<label>项目名称（可以修改）<input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="例如我的产品"/></label><label>本地测试网址（必填）<input value={form.targetUrl} onChange={(event) => setForm({ ...form, targetUrl: event.target.value })}/>{fields.targetUrl && <span className="field-error">{fields.targetUrl}</span>}</label>{fields.projectRoot && <span className="field-error">{fields.projectRoot}</span>}<details className="advanced"><summary>高级详情：项目文件夹和 Agent 来源</summary><label>项目文件夹<input value={form.projectRoot} onChange={(event) => setForm({ ...form, projectRoot: event.target.value, importSource: 'manual', preferredAgent: null })} placeholder="/path/to/project"/></label><div>{agents.loading ? <Skeleton rows={1}/> : agents.error ? <p className="inline-error">开发工具状态读取失败：{agents.error}</p> : agents.data?.map((agent) => <p key={agent.provider}><b>{agent.displayName}：</b>{agent.capabilities?.workspaceDiscovery ? '可以读取近期项目路径' : '不读取会话文件，请使用 Mac 文件夹选择器'}</p>)}</div></details></section>{error && <p className="inline-error">{error}</p>}</form></Modal>}<Toast message={notice}/></>;
}

function EvaluatePage({ active, go }: { active: Json | null; go: (page: PageKey) => void }) {
  const blueprint = useApi<Json>('/blueprint'); const personas = useApi<Json[]>('/personas'); const cases = useApi<Json>('/cases?page=1&pageSize=100'); const journeys = useApi<Json[]>('/journeys'); const history = useApi<Json[]>(active ? `/evaluations?projectId=${active.projectId}` : null); const depthOptions = useApi<Json[]>(active ? `/evaluation-depths?projectId=${active.projectId}` : null);
  const [depth, setDepth] = useState('core'); const [selected, setSelected] = useState<string[]>([]); const [session, setSession] = useState<Json | null>(null); const [events, setEvents] = useState<string[]>([]); const [error, setError] = useState<string | null>(null);
  function watch(evaluationId: string) { const stream = new EventSource(`/api/evaluations/${encodeURIComponent(evaluationId)}/events`); stream.addEventListener('evaluation.progress', async (raw) => { const event = JSON.parse((raw as MessageEvent).data) as Json; setEvents((items) => [...items, event.message]); try { const current = await apiRequest<Json>(`/evaluations/${evaluationId}`); setSession(current.session); if (current.session.status === 'completed' || current.session.status === 'failed') { stream.close(); history.reload(); if (current.session.status === 'failed') setError(current.session.error ?? '评测未完成。'); else { setError(null); window.setTimeout(() => go('issues'), 800); } } } catch { /* 下一事件会重试快照读取。 */ } }); stream.onerror = () => stream.close(); }
  async function start() { if (!active) return; setError(null); setEvents([]); try { const started = await apiRequest<Json>('/evaluations', { method: 'POST', body: JSON.stringify({ projectId: active.projectId, depth, capabilityIds: selected }) }); setSession(started); watch(started.evaluationId); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } }
  async function resume(evaluationId: string) { setError(null); setEvents([]); try { const resumed = await apiRequest<Json>(`/evaluations/${evaluationId}/retry`, { method: 'POST', body: JSON.stringify({ confirmed: true }) }); setSession(resumed); watch(evaluationId); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } }
  if (!active) return <><PageHeader step="02 / EVALUATE" title="运行产品评测" intro="先选择项目。"/><EmptyState title="没有当前项目" detail="返回项目页添加或选择一个项目。" action={<Button onClick={() => go('projects')}>返回项目</Button>}/></>;
  const capabilities = blueprint.data?.capabilities ?? []; const recoverable = session?.status === 'failed' ? session : history.data?.find((item) => item.status === 'failed');
  const fallbackDepths = [{ depth: 'quick', label: '快速检查', summary: '1 条最关键路径', suitableFor: '适合修改后立即检查', durationLabel: '耗时最短', estimatedCaseCount: 1, estimatedDurationMinutes: null, recommended: false }, { depth: 'core', label: '核心评测', summary: '关键功能，最多 3 条探索路径', suitableFor: '适合提测或上线前', durationLabel: '耗时适中', estimatedCaseCount: 3, estimatedDurationMinutes: null, recommended: true }, { depth: 'full', label: '完整评测', summary: '所选功能的固定、探索与回归案例', suitableFor: '适合重要版本验收', durationLabel: '耗时最长', estimatedCaseCount: null, estimatedDurationMinutes: null, recommended: false }];
  const displayedDepths = depthOptions.data ?? fallbackDepths;
  return <><PageHeader step="02 / EVALUATE" title="选择目标并开始评测" intro="系统会自动完成扫描、理解产品、生成案例、真实浏览器运行和报告。默认核心评测。" action={<Badge tone="success">{active.name}</Badge>}/>{error && <ErrorPanel message={error} retry={recoverable ? () => resume(recoverable.evaluationId) : start}/>} {!error && recoverable && !session && <section className="inline-error"><b>上次评测在“{stageLabels[recoverable.currentStage]}”停止：</b>{recoverable.error}<div className="card-actions"><Button onClick={() => resume(recoverable.evaluationId)}>从失败阶段继续</Button></div></section>}<section className="panel"><div className="card-heading"><div><h2>1. 评测深度</h2><p>覆盖说明与实际运行范围保持一致。</p></div>{depthOptions.loading && <Badge>正在估算</Badge>}</div>{depthOptions.error && <p className="inline-error">深度估算读取失败，先显示默认范围：{depthOptions.error}</p>}<div className="choice-grid">{displayedDepths.map((option) => <label className={`choice-card ${depth === option.depth ? 'selected' : ''}`} key={option.depth}><input type="radio" name="depth" value={option.depth} checked={depth === option.depth} onChange={() => setDepth(option.depth)}/><div className="card-heading"><b>{option.label}</b>{option.recommended && <Badge tone="success">推荐</Badge>}</div><span>{option.summary}</span><small>{option.suitableFor}</small><small>{option.estimatedDurationMinutes ? `历史平均约 ${option.estimatedDurationMinutes} 分钟` : option.durationLabel}{option.estimatedCaseCount ? ` · 预计 ${option.estimatedCaseCount} 个案例` : ''}</small></label>)}</div></section>
    <section className="panel"><div className="card-heading"><div><h2>2. 选择功能</h2><p>不选择时，系统会按重要度自动决定。</p></div><Badge>{selected.length ? `${selected.length} 个已选` : '自动选择'}</Badge></div>{blueprint.loading ? <Skeleton rows={2}/> : blueprint.error ? <p className="muted">首次评测会自动生成可选功能，无需提前设置。</p> : <div className="capability-picker">{capabilities.map((capability: Json) => <label key={capability.id}><input type="checkbox" checked={selected.includes(capability.id)} onChange={(event) => setSelected(event.target.checked ? [...selected, capability.id] : selected.filter((id) => id !== capability.id))}/><span><b>{capability.name}</b><small>{capability.userGoals?.[0]}</small></span><Badge tone={capability.importance === 'critical' ? 'danger' : 'neutral'}>{capability.importance}</Badge></label>)}</div>}</section>
    <section className="next-action"><div><span className="eyebrow">READY</span><h2>{session?.status === 'running' ? `正在进行：${stageLabels[session.currentStage]}` : '准备运行一次真实评测'}</h2><p>{session?.status === 'running' ? events.at(-1) : '评测期间会打开本地 Chromium，并保存截图和可复现轨迹。'}</p></div><Button disabled={session?.status === 'running'} onClick={start}>{session?.status === 'running' ? '评测进行中…' : '开始评测'}</Button></section>
    {session && <section className="pipeline">{stages.map((name, index) => { const item = session.stages?.find((stage: Json) => stage.name === name); return <article className={item?.status ?? 'pending'} key={name}><span>{String(index + 1).padStart(2,'0')}</span><div><b>{stageLabels[name]}</b><small>{item?.message ?? '等待前一步'}</small></div><Badge tone={item?.status === 'completed' ? 'success' : item?.status === 'failed' ? 'danger' : item?.status === 'running' ? 'purple' : 'neutral'}>{item?.status ?? 'pending'}</Badge></article>; })}</section>}
    <details className="advanced"><summary>高级详情：Persona、案例与旅程</summary>{[personas.error, cases.error, journeys.error, history.error].filter(Boolean).length > 0 && <p className="inline-error">部分高级详情读取失败：{[personas.error, cases.error, journeys.error, history.error].filter(Boolean).join('；')}</p>}<div className="metrics-grid"><article className="metric"><span>模拟用户</span><strong>{personas.data?.length ?? 0}</strong><small>行为差异</small></article><article className="metric"><span>案例</span><strong>{cases.data?.total ?? 0}</strong><small>固定＋探索</small></article><article className="metric"><span>旅程</span><strong>{journeys.data?.length ?? 0}</strong><small>四层完成</small></article><article className="metric"><span>历史评测</span><strong>{history.data?.length ?? 0}</strong><small>每项目隔离</small></article></div></details></>;
}

function IssuesPage({ active, go }: { active: Json | null; go: (page: PageKey) => void }) {
  const [selectedEvaluationId, setSelectedEvaluationId] = useState(''); const [featureFilter, setFeatureFilter] = useState('all'); const [depthFilter, setDepthFilter] = useState('all'); const [resultFilter, setResultFilter] = useState('all');
  const records = useApi<Json[]>(active ? `/evaluation-records?projectId=${encodeURIComponent(active.projectId)}` : null); const effectiveEvaluationId = records.data?.some((item) => item.evaluationId === selectedEvaluationId) ? selectedEvaluationId : records.data?.[0]?.evaluationId ?? '';
  const issues = useApi<Json[]>(active ? `/issues?projectId=${encodeURIComponent(active.projectId)}${effectiveEvaluationId ? `&evaluationId=${encodeURIComponent(effectiveEvaluationId)}` : ''}` : null); const report = useApi<Json>(active ? `/reports/latest?projectId=${encodeURIComponent(active.projectId)}${effectiveEvaluationId ? `&evaluationId=${encodeURIComponent(effectiveEvaluationId)}` : ''}` : null);
  const [detail, setDetail] = useState<Json | null>(null); const [dismiss, setDismiss] = useState<Json | null>(null); const [fix, setFix] = useState<Json | null>(null); const [rename, setRename] = useState<Json | null>(null); const [renameValue, setRenameValue] = useState(''); const [busy, setBusy] = useState(false); const [message, setMessage] = useState<string | null>(null); const [error, setError] = useState<string | null>(null);
  useEffect(() => { if (records.data?.length && !records.data.some((item) => item.evaluationId === selectedEvaluationId)) setSelectedEvaluationId(records.data[0].evaluationId); }, [records.data, selectedEvaluationId]);
  async function dismissIssue() { if (!dismiss) return; setBusy(true); try { await apiRequest(`/issues/${dismiss.issueId}/dismiss`, { method: 'POST', body: JSON.stringify({ confirmed: true }) }); setDismiss(null); issues.reload(); setMessage('已标记为暂不处理。'); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } finally { setBusy(false); } }
  async function createFix() { if (!fix || !active) return; setBusy(true); try { await apiRequest('/fix-tasks', { method: 'POST', body: JSON.stringify({ projectId: active.projectId, issueId: fix.issueId, confirmed: true }) }); setFix(null); setMessage('修复任务包已生成。'); go('fixes'); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } finally { setBusy(false); } }
  async function saveRename() { if (!rename || !renameValue.trim()) return; setBusy(true); setError(null); try { await apiRequest(`/evaluations/${rename.evaluationId}`, { method: 'PATCH', body: JSON.stringify({ customName: renameValue.trim() }) }); setRename(null); setRenameValue(''); records.reload(); setMessage('评测名称已更新。'); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } finally { setBusy(false); } }
  if (!active) return <><PageHeader step="03 / ISSUES" title="看懂评测问题" intro="先选择项目。"/><EmptyState title="没有当前项目" detail="返回项目页选择要查看的项目。"/></>;
  if (issues.error) return <><PageHeader step="03 / ISSUES" title="评测发现了什么" intro="问题和证据没有成功读取。"/><ErrorPanel message={issues.error} retry={issues.reload}/></>;
  if (issues.loading || records.loading) return <Skeleton rows={6}/>; const visible = (issues.data ?? []).filter((item) => !item.dismissed); const worst = [...visible].sort((a,b) => Number(a.severity.slice(1)) - Number(b.severity.slice(1)))[0]; const selectedRecord = records.data?.find((item) => item.evaluationId === effectiveEvaluationId); const completed = report.data?.metrics?.fullLoopCompleted ?? selectedRecord?.verdict === 'can_continue';
  const featureOptions = [...new Set((records.data ?? []).flatMap((item) => item.capabilityNames ?? []))]; const filteredRecords = (records.data ?? []).filter((item) => (featureFilter === 'all' || item.capabilityNames?.includes(featureFilter)) && (depthFilter === 'all' || item.depth === depthFilter) && (resultFilter === 'all' || item.verdict === resultFilter));
  return <><PageHeader step="03 / ISSUES" title="评测发现了什么" intro="先看能否完成用户目标，再看证据和修复建议。模拟用户结果不等于真实用户满意度。" action={<Badge tone={worst ? 'warning' : 'success'}>{worst ? `${visible.length} 个待处理` : '本轮无结构化问题'}</Badge>}/>{error && <ErrorPanel message={error} retry={issues.reload}/>} {records.error && <p className="inline-error">评测记录读取失败：{records.error}</p>}<section className="record-history"><div className="record-toolbar"><div><h2>评测记录</h2><small>选择一张卡片，结论、问题和证据会一起切换。</small></div><div className="record-filters"><label>功能<select value={featureFilter} onChange={(event) => setFeatureFilter(event.target.value)}><option value="all">全部功能</option>{featureOptions.map((name) => <option key={name}>{name}</option>)}</select></label><label>深度<select value={depthFilter} onChange={(event) => setDepthFilter(event.target.value)}><option value="all">全部深度</option><option value="quick">快速检查</option><option value="core">核心评测</option><option value="full">完整评测</option></select></label><label>结果<select value={resultFilter} onChange={(event) => setResultFilter(event.target.value)}><option value="all">全部结果</option><option value="can_continue">可以继续</option><option value="needs_attention">需要处理</option><option value="unknown">未完成</option></select></label></div></div>{!filteredRecords.length ? <EmptyState title="没有符合筛选的评测" detail="调整功能、深度或结果筛选后再试。"/> : <div className="record-rail">{filteredRecords.map((record) => <article className={`record-card ${effectiveEvaluationId === record.evaluationId ? 'selected' : ''}`} key={record.evaluationId}><button className="record-select" onClick={() => setSelectedEvaluationId(record.evaluationId)} aria-pressed={effectiveEvaluationId === record.evaluationId}><span className="record-sequence">#{record.sequenceNumber}</span><b>{record.displayName}</b><small>{record.capabilityNames?.join('、') || '旧记录'} · {record.depth === 'quick' ? '快速检查' : record.depth === 'full' ? '完整评测' : '核心评测'}</small><div className="record-meta"><Badge tone={record.status === 'completed' ? 'success' : record.status === 'failed' ? 'danger' : 'purple'}>{record.status === 'completed' ? '已完成' : record.status === 'failed' ? '未完成' : '进行中'}</Badge><span>{record.severeIssueCount} 个 P0/P1</span><span>{formatDuration(record.durationMs)}</span></div>{record.legacyEvidenceIncomplete && <em>旧记录，证据关联不完整</em>}</button><button className="record-rename" onClick={() => { setRename(record); setRenameValue(record.displayName); }}>重命名</button></article>)}</div>}</section>{report.error && <p className="inline-error">当前评测的完整报告读取失败：{report.error}</p>}<section className="report-hero"><div><span className="eyebrow">EVALUATION #{selectedRecord?.sequenceNumber ?? '—'}</span><h2>{completed ? '核心任务形成完整闭环' : '核心任务闭环仍有缺口'}</h2><p>{worst ? `最优先处理：${issueLabels[worst.type] ?? worst.type}` : '当前模拟运行没有生成结构化问题，但仍需要真实用户验证。'}</p></div><div className={`signal ${completed ? 'good' : 'warn'}`}>{completed ? '可以继续' : '需要处理'}</div></section>
    {!visible.length ? <EmptyState title="当前没有待处理问题" detail="可以运行其他功能或更完整的评测；这不代表真实用户体验已经被证明。" action={<Button onClick={() => go('evaluate')}>评测其他功能</Button>}/> : <section className="issue-board">{visible.map((issue) => <article className="issue-card" key={issue.issueId}><div className="card-heading"><Badge tone={issue.severity === 'P0' || issue.severity === 'P1' ? 'danger' : 'warning'}>{issue.severity}</Badge><Badge>{issue.confidence} 置信度</Badge></div><h2>{issueLabels[issue.type] ?? issue.type}</h2><p><b>发生了什么：</b>{issue.failureOrAbandonmentPoint ?? issue.actualPath?.at(-1) ?? '用户没有完成目标'}</p><p><b>用户影响：</b>无法顺利完成“{issue.userGoal}”。</p><p><b>建议：</b>{issue.recommendation}</p><div className="card-actions"><Button tone="secondary" onClick={() => setDetail(issue)}>查看证据</Button><Button tone="secondary" onClick={() => setDismiss(issue)}>暂不处理</Button><Button onClick={() => setFix(issue)}>选择 AI 修复</Button></div></article>)}</section>}
    {detail && <Modal title={issueLabels[detail.type] ?? detail.type} onClose={() => setDetail(null)} actions={<Button onClick={() => setDetail(null)}>我看完了</Button>}><div className="evidence-detail"><h3>实际路径</h3><p>{detail.actualPath?.join(' → ')}</p><h3>期望路径</h3><p>{detail.shortestReasonablePath?.join(' → ')}</p><h3>证据</h3><div className="evidence-grid">{detail.evidence?.map((path: string) => path.match(/\.(png|jpg|jpeg|webp)$/i) ? <figure key={path}><img src={`/api/evidence-file?path=${encodeURIComponent(path)}`} alt="评测截图"/><figcaption>{path.split('/').at(-1)}</figcaption></figure> : <a key={path} href={`/api/evidence-file?path=${encodeURIComponent(path)}`} target="_blank" rel="noreferrer">打开 {path.split('/').at(-1)}</a>)}</div><p className="authenticity">这是模拟用户和工程证据，不代表真实用户满意度或业务效果。</p></div></Modal>}
    {dismiss && <Modal title="暂不处理这个问题？" onClose={() => setDismiss(null)} actions={<><Button tone="secondary" disabled={busy} onClick={() => setDismiss(null)}>取消</Button><Button disabled={busy} onClick={dismissIssue}>{busy ? '正在保存…' : '确认暂不处理'}</Button></>}><p>问题会从待办列表隐藏，但证据和历史记录仍会保留。</p></Modal>}
    {fix && <Modal title="生成可交给 AI 的修复任务" onClose={() => setFix(null)} actions={<><Button tone="secondary" disabled={busy} onClick={() => setFix(null)}>取消</Button><Button disabled={busy} onClick={createFix}>{busy ? '正在生成任务…' : '确认并生成任务包'}</Button></>}><p><b>{issueLabels[fix.type] ?? fix.type}</b></p><p>{fix.recommendation}</p><p><b>允许修改范围：</b><span className="mono">src/**、tests/**、docs/**</span></p><p><b>验收标准：</b>项目已有检查通过，并复跑同一个评测案例；完整闭环和安全确认不得退化。</p><ul><li>生成 task.md 和 task.json，不会修改目标项目。</li><li>可交给 Codex、Claude Code、Antigravity 或其他 Agent。</li><li>Public Alpha 暂不自动执行或合并修复。</li></ul></Modal>}
    {rename && <Modal title="重命名评测记录" onClose={() => setRename(null)} actions={<><Button tone="secondary" disabled={busy} onClick={() => setRename(null)}>取消</Button><Button disabled={busy || !renameValue.trim()} onClick={saveRename}>{busy ? '正在保存…' : '保存名称'}</Button></>}><label className="rename-field">评测名称（必填）<input autoFocus value={renameValue} maxLength={80} onChange={(event) => setRenameValue(event.target.value)}/>{!renameValue.trim() && <span className="field-error">请输入评测名称。</span>}</label></Modal>}<Toast message={message}/></>;
}

function FixesPage({ active }: { active: Json | null }) {
  const tasks = useApi<Json[]>(active ? `/fix-tasks?projectId=${active.projectId}` : '/fix-tasks?projectId=none'); const [confirm, setConfirm] = useState<{ task: Json; action: 'package'|'apply' } | null>(null); const [busy, setBusy] = useState(false); const [events] = useState<string[]>([]); const [agent, setAgent] = useState<Json | null>(null); const [runsByTask, setRunsByTask] = useState<Record<string, Json[]>>({}); const [error, setError] = useState<string | null>(null); const [message, setMessage] = useState<string | null>(null);
  useEffect(() => { let current = true; if (!tasks.data?.length) { setRunsByTask({}); return () => { current = false; }; } Promise.all(tasks.data.map(async (task) => [task.fixTaskId, await apiRequest<Json[]>(`/fix-tasks/${task.fixTaskId}/agent-runs`)] as const)).then((entries) => { if (current) setRunsByTask(Object.fromEntries(entries)); }).catch((cause) => { if (current) setError(cause instanceof Error ? cause.message : String(cause)); }); return () => { current = false; }; }, [tasks.data]);
  async function perform() { if (!confirm) return; setBusy(true); setError(null); try { if (confirm.action === 'apply') { if (!agent?.agentRunId || agent.fixTaskId !== confirm.task.fixTaskId || !agent.verification?.safeToApply) throw new Error('请选择一次已经通过验证的 Agent 尝试。'); await apiRequest(`/fix-tasks/${confirm.task.fixTaskId}/apply`, { method: 'POST', body: JSON.stringify({ confirmed: true, agentRunId: agent.agentRunId }) }); setMessage('修复已应用到当前项目。'); tasks.reload(); setConfirm(null); return; } const run = await apiRequest<Json>(`/fix-tasks/${confirm.task.fixTaskId}/run`, { method: 'POST', body: JSON.stringify({ confirmed: true, adapter: 'task_package' }) }); setAgent(run); setConfirm(null); setMessage('通用任务包已经生成，可交给 Codex、Claude Code、Antigravity 或其他 Agent。'); tasks.reload(); } catch (cause) { setError(cause instanceof Error ? cause.message : String(cause)); } finally { setBusy(false); } }
  if (!active) return <><PageHeader step="04 / FIXES" title="让 Agent 修复并复测" intro="先选择项目。"/><EmptyState title="没有当前项目" detail="返回项目页选择项目。"/></>; if (tasks.loading) return <Skeleton rows={5}/>; if (tasks.error) return <><PageHeader step="04 / FIXES" title="修复、验证，再决定是否应用" intro="修复任务没有成功读取。"/><ErrorPanel message={tasks.error} retry={tasks.reload}/></>;
  return <><PageHeader step="04 / FIXES" title="生成任务包，再交给 AI 修复" intro="Public Alpha 暂不自动修改代码；Codex、Claude Code、Antigravity 和其他 Agent 使用同一任务包交接。" action={<Badge tone="success">目标工作区不会被自动修改</Badge>}/>{error && <ErrorPanel message={error} retry={tasks.reload}/>} {!tasks.data?.length ? <EmptyState title="还没有修复任务" detail="先在问题页查看证据，确认后再创建修复任务。"/> : <section className="fix-list">{tasks.data.map((task) => { const runs = runsByTask[task.fixTaskId] ?? []; const latestRun = agent?.fixTaskId === task.fixTaskId ? agent : runs[0]; const verifiedRun = runs.find((run) => run.verification?.safeToApply) ?? (latestRun?.verification?.safeToApply ? latestRun : null); return <article className="fix-card" key={task.fixTaskId}><div className="card-heading"><Badge tone={task.status === 'ready_to_apply' ? 'success' : task.status === 'failed' || task.status === 'blocked' ? 'danger' : 'purple'}>{task.status}</Badge><span className="mono">{latestRun?.branch ?? '尚未创建修复分支'}</span></div><h2>{task.issueId}</h2><p>任务包：<span className="mono">{task.taskDirectory}</span></p><div className="verification-grid"><div><span>代码隔离</span><b>{latestRun?.worktreePath ? '已创建独立 worktree' : '等待外部 Agent'}</b></div><div><span>项目检查</span><b>{latestRun?.verification?.tests?.length ? latestRun.verification.tests.every((item: Json) => item.status === 'passed') ? '通过' : '有失败' : latestRun?.executionMode === 'handoff' ? '等待外部 Agent' : '等待运行'}</b></div><div><span>修复复测</span><b>{latestRun?.verification?.verdict ?? '等待运行'}</b></div></div>{latestRun?.requiresUserAction && <p>{latestRun.requiresUserAction}</p>}{latestRun?.verification?.blockers?.length ? <div className="inline-error">{latestRun.verification.blockers.join('；')}</div> : null}<div className="card-actions"><Button tone="secondary" onClick={() => setConfirm({ task, action: 'package' })}>生成／更新任务包</Button>{verifiedRun && <Button onClick={() => { setAgent(verifiedRun); setConfirm({ task, action: 'apply' }); }}>应用这次已验证修复</Button>}</div></article>; })}</section>}
    {(agent || events.length > 0) && <section className="panel agent-console"><div className="card-heading"><h2>Agent 实时状态</h2><Badge tone={agent?.status === 'failed' ? 'danger' : agent?.status === 'completed' ? 'success' : 'purple'}>{agent?.status ?? 'running'}</Badge></div><div className="console-lines">{events.map((event, index) => <p key={`${event}-${index}`}>{event}</p>)}</div>{agent?.changedFiles?.length ? <div><h3>修改文件</h3><ul>{agent.changedFiles.map((file: string) => <li className="mono" key={file}>{file}</li>)}</ul></div> : null}</section>}
    {confirm && <Modal title={confirm.action === 'apply' ? '确认应用修复？' : '生成通用任务包'} onClose={() => setConfirm(null)} actions={<><Button tone="secondary" disabled={busy} onClick={() => setConfirm(null)}>取消</Button><Button disabled={busy} onClick={perform}>{busy ? '正在处理…' : confirm.action === 'apply' ? '确认应用修复' : '生成任务包'}</Button></>}><p>{confirm.action === 'apply' ? `将应用已通过验证的尝试 ${agent?.agentRunId ?? '尚未选择'}；当前项目有未提交改动时会停止并保留修复分支。` : '只生成 task.md 和 task.json，不会修改目标项目；可交给 Codex、Claude Code、Antigravity 或其他 Agent。'}</p></Modal>}<Toast message={message}/></>;
}

export function App() {
  const [page, setPage] = useState<PageKey>(routePage); const [menuOpen, setMenuOpen] = useState(false); const health = useApi<Json>('/health'); const serviceCompatible = health.data?.contractVersion === '0.6.0'; const registry = useApi<Json>(serviceCompatible ? '/projects' : null); const active = registry.data?.projects?.find((item: Json) => item.projectId === registry.data?.activeProjectId) ?? null;
  const navigate = useCallback<Navigate>((target) => { const path = target.startsWith('/') ? target : `/${target}`; window.history.pushState({}, '', path); setPage(routePage()); setMenuOpen(false); }, []); useEffect(() => { const handler = () => setPage(routePage()); window.addEventListener('popstate', handler); return () => window.removeEventListener('popstate', handler); }, []); useEffect(() => { const id = window.location.hash.slice(1); if (!id) return; const observer = new MutationObserver(() => { if (document.getElementById(id)) { focusAnchor(id); observer.disconnect(); } }); observer.observe(document.body, { childList: true, subtree: true }); focusAnchor(id); const timeout = window.setTimeout(() => observer.disconnect(), 4000); return () => { observer.disconnect(); window.clearTimeout(timeout); }; }, [page]);
  const pageContent = registry.error ? <ErrorPanel message={registry.error} retry={registry.reload}/> : registry.loading || !registry.data ? <Skeleton rows={6}/> : page === 'home' ? <HomePage active={active} go={navigate}/> : page === 'projects' ? <ProjectsPage registry={registry.data} reload={registry.reload} go={navigate}/> : page === 'evaluate' ? <GuidedEvaluatePage active={active} go={navigate}/> : page === 'issues' ? <GuidedIssuesPage active={active} go={navigate}/> : page === 'eval-set' ? <EvalSetPage active={active} go={navigate}/> : page === 'runs' ? <RunsPage active={active} go={navigate}/> : page === 'findings' ? <FindingsPage active={active} go={navigate}/> : page === 'regression' ? <RegressionPage active={active} go={navigate}/> : <FixesPage active={active}/>;
  const content = health.loading ? <Skeleton rows={6}/> : health.error ? <ServiceRecovery message={health.error} retry={health.reload}/> : !serviceCompatible ? <ServiceRecovery message={`当前页面需要 0.6.0，本地服务返回 ${health.data?.contractVersion ?? '未知版本'}。请重启 EvalPilot 后重新连接。`} retry={health.reload}/> : <>{health.data?.runtime?.checks?.chromium?.status !== 'ready' && <section className="state-card" role="status"><span className="state-icon">!</span><div><h2>浏览器评测尚未就绪</h2><p>{health.data?.runtime?.checks?.chromium?.detail}</p><details className="advanced"><summary>查看恢复方法</summary><p className="mono">evalpilot setup --install-chromium --confirmed</p></details></div></section>}{pageContent}</>;
  const currentLabel = useMemo(() => pageLabels[page], [page]);
  return <div className="app-shell"><aside className={`sidebar ${menuOpen ? 'open' : ''}`}><button className="brand" onClick={() => navigate('home')} aria-label="打开使用说明"><span className="brand-mark">EP</span><span><b>EvalPilot</b><small>LOCAL OBSERVATORY</small></span></button><nav aria-label="产品闭环">{navigation.map((item, index) => <button aria-current={page === item.key ? 'page' : undefined} key={item.key} onClick={() => navigate(item.key)}><span>{String(index + 1).padStart(2, '0')}</span><div><b>{item.label}</b><small>{item.note}</small></div></button>)}</nav><footer><Badge tone="success">● 仅本机</Badge><p>评测资产只保存在本机</p></footer></aside>{menuOpen && <button className="scrim" aria-label="关闭导航" onClick={() => setMenuOpen(false)}/>}<section className="workspace"><header className="topbar"><button className="menu-button" onClick={() => setMenuOpen(true)} aria-label="打开主导航">☰</button><div><span>EvalPilot /</span><b>{currentLabel}</b></div><div className="active-project"><span>{active?.name ?? '尚未选择项目'}</span><Badge tone={active?.status === 'ready' ? 'success' : 'warning'}>{active?.status === 'ready' ? '● 可评测' : '○ 待连接'}</Badge></div></header><main>{content}</main></section></div>;
}
